};

const prop = (args.proporcion || '9:16').trim();
const validos = ['9:16', '1:1', '3:4', '4:3', '16:9'];
if (validos.includes(prop)) {
  return { aspect_ratio_gemini: prop };
}
if (prop === '4:5') {
  return { aspect_ratio_gemini: '3:4' };
}
return { aspect_ratio_gemini: '9:16' };

if (!args.concepto || typeof args.concepto !== 'string') {
  throw new Error("El concepto es requerido.");
}
const concepto = args.concepto.trim();
const estilo = (args.estilo || 'lifestyle').toLowerCase().trim();

let mod = "estilo Instagram lifestyle, iluminacion natural suave, composicion cuidada, alta definicion";
if (estilo === 'cinematic') {
  mod = "estilo cinematografico, iluminacion dramatica, profundidad de campo, alta resolucion 8k";
} else if (estilo === 'minimalist') {
  mod = "estilo minimalista contemporaneo, composicion limpia, tonos suaves, estetica moderna";
}

return {
  prompt_final: `${concepto}. ${mod}.`
};

if (!args.prompt || typeof args.prompt !== 'string') {
  throw new Error("El parámetro 'prompt' es requerido.");
}

const apiKey = ctx.env.GEMINI_API_KEY;
if (!apiKey) {
  return {
    exito: false,
    error: "No se encontró la clave GEMINI_API_KEY. Por favor configúrala en Ajustes -> Claves y variables como AGENT_BANANO_GEMINI_API_KEY.",
    sugerencia: "Agrega tu API Key de Google Gemini / AI Studio para que Banano pueda generar las imágenes."
  };
}

let ratio = (args.aspect_ratio || '9:16').trim();
const validRatios = ['9:16', '1:1', '3:4', '4:3', '16:9'];
if (!validRatios.includes(ratio)) {
  if (ratio === '4:5') {
    ratio = '3:4';
  } else {
    ratio = '9:16';
  }
}

let ancho = typeof args.ancho === 'number' && args.ancho > 0 ? Math.min(args.ancho, 1920) : (ratio === '9:16' ? 1080 : (ratio === '16:9' ? 1920 : 1080));
let alto = typeof args.alto === 'number' && args.alto > 0 ? Math.min(args.alto, 1920) : (ratio === '9:16' ? 1920 : (ratio === '16:9' ? 1080 : 1080));

const endpoint = `https://generativelanguage.googleapis.com/v1beta/models/imagen-3.0-generate-002:predict?key=${encodeURIComponent(apiKey)}`;

const payload = {
  instances: [
    {
      prompt: args.prompt.trim()
    }
  ],
  parameters: {
    sampleCount: 1,
    aspectRatio: ratio,
    outputMimeType: "image/jpeg",
    personGeneration: "ALLOW_ADULT",
    safetySetting: "block_medium_and_above"
  }
};

const res = await ctx.fetch(endpoint, {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json'
  },
  body: JSON.stringify(payload)
});

if (!res.ok) {
  let errorMsg = `HTTP ${res.status}`;
  try {
    const errObj = typeof res.json === 'function' ? await res.json() : (typeof res.json === 'object' && res.json !== null ? res.json : JSON.parse(res.text || '{}'));
    if (errObj.error && errObj.error.message) {
      errorMsg = errObj.error.message;
    }
  } catch (e) {}
  return {
    exito: false,
    status: res.status,
    error: `Error al generar imagen con Gemini: ${errorMsg}`
  };
}

const data = typeof res.json === 'function' ? await res.json() : (typeof res.json === 'object' && res.json !== null ? res.json : JSON.parse(res.text || '{}'));
const prediction = (data.predictions && data.predictions[0]) ? data.predictions[0] : null;

if (!prediction || !prediction.bytesBase64Encoded) {
  return {
    exito: false,
    error: "No se recibió ninguna imagen de Gemini Imagen 3.",
    respuesta: JSON.stringify(data).slice(0, 300)
  };
}

const mime = prediction.mimeType || 'image/jpeg';
const base64 = prediction.bytesBase64Encoded;

return {
  exito: true,
  modelo: "imagen-3.0-generate-002",
  prompt: args.prompt.trim(),
  aspect_ratio: ratio,
  dimensiones: {
    ancho_px: ancho,
    alto_px: alto,
    maximo_px: 1920
  },
  mime_type: mime,
  tamano_base64_caracteres: base64.length,
  data_url: `data:${mime};base64,${base64}`
};
